Cependant, si vous souhaitez simplement créer un serveur HTTP simple pour des tests ou des prototypages, voici un exemple de code simple en C# utilisant HttpListener :

```csharp
using System;
using System.Net;

class Program
{
    static void Main()
    {
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/");
        listener.Start();

        Console.WriteLine("Server started at http://localhost:8080/");
        Console.WriteLine("Press Enter to stop the server...");

        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            context.Response.StatusCode = 200;
            context.Response.ContentType = "text/plain";

            byte[] buffer = System.Text.Encoding.UTF8.GetBytes("Hello, World!");
            context.Response.OutputStream.Write(buffer, 0, buffer.Length);
            context.Response.OutputStream.Close();
        }

        listener.Stop();
    }
}
```

